// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialDrugs, uint256 ethForBuy, uint256 collectAmount) public {
        // Ensure the contract is seeded first
        vm.assume(initialDrugs > 0 && initialDrugs < 1e30);
        vm.assume(ethForBuy > 0 && ethForBuy < 10 ether);
        vm.assume(collectAmount > 0 && collectAmount < 1e18);

        // Seed the market
        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 0.1 ether}(initialDrugs);

        // Give the caller some initial drugs by buying
        vm.deal(address(this), ethForBuy + 1 ether);
        c.buyDrugs{value: ethForBuy}();

        // Get initial marketDrugs
        uint256 marketBefore = c.marketDrugs();

        // Record drugs used before collect
        uint256 drugsBefore = c.getMyDrugs();

        // Call collectDrugs with a referral
        vm.assume(drugsBefore > 0);
        c.collectDrugs(address(0));

        // Get marketDrugs after
        uint256 marketAfter = c.marketDrugs();

        // The correct behavior: marketDrugs increases by drugsUsed/10
        assertTrue(marketAfter - marketBefore == (drugsBefore / 10));
    }
}

